/**
 * Lightweight Standalone QRCode Generator (SVG / Canvas)
 * Pure JavaScript, zero dependencies, self-contained for offline use.
 */
(function(window) {
  function QRCode(target, options) {
    if (typeof options === "string") {
      options = { text: options };
    }
    this.options = Object.assign({
      width: 200,
      height: 200,
      text: "",
      correctLevel: 2
    }, options);

    if (typeof target === "string") {
      this.target = document.getElementById(target);
    } else {
      this.target = target;
    }

    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  // QRCode Matrix Generation (Type 4, ECL M)
  QRCode.prototype.makeCode = function(text) {
    if (!this.target) return;
    this.target.innerHTML = "";

    // Generate SVG QR Code
    var size = this.options.width;
    var qr = createQRMatrix(text);
    var moduleCount = qr.length;
    var cellSize = size / moduleCount;

    var svg = ['<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '">'];
    svg.push('<rect width="100%" height="100%" fill="#ffffff"/>');

    for (var r = 0; r < moduleCount; r++) {
      for (var c = 0; c < moduleCount; c++) {
        if (qr[r][c]) {
          var x = (c * cellSize).toFixed(2);
          var y = (r * cellSize).toFixed(2);
          var w = (cellSize + 0.1).toFixed(2);
          var h = (cellSize + 0.1).toFixed(2);
          svg.push('<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" fill="#0f172a"/>');
        }
      }
    }
    svg.push('</svg>');
    this.target.innerHTML = svg.join("");
  };

  // Helper function to create QR Matrix with Finder Patterns & Data Encoding
  function createQRMatrix(text) {
    var size = 25; // 25x25 grid (Version 2)
    var matrix = [];
    for (var i = 0; i < size; i++) {
      matrix[i] = [];
      for (var j = 0; j < size; j++) {
        matrix[i][j] = false;
      }
    }

    function addFinderPattern(x, y) {
      for (var r = -1; r <= 7; r++) {
        for (var c = -1; c <= 7; c++) {
          if (x + r >= 0 && x + r < size && y + c >= 0 && y + c < size) {
            if ((r >= 0 && r <= 6 && (c === 0 || c === 6)) ||
                (c >= 0 && c <= 6 && (r === 0 || r === 6)) ||
                (r >= 2 && r <= 4 && c >= 2 && c <= 4)) {
              matrix[x + r][y + c] = true;
            } else {
              matrix[x + r][y + c] = false;
            }
          }
        }
      }
    }

    // Add 3 Finder Patterns
    addFinderPattern(0, 0);
    addFinderPattern(0, size - 7);
    addFinderPattern(size - 7, 0);

    // Timing Patterns
    for (var t = 8; t < size - 8; t++) {
      matrix[6][t] = (t % 2 === 0);
      matrix[t][6] = (t % 2 === 0);
    }

    // Alignment Pattern for Version 2
    var ax = 18, ay = 18;
    for (var ar = -2; ar <= 2; ar++) {
      for (var ac = -2; ac <= 2; ac++) {
        if (Math.abs(ar) === 2 || Math.abs(ac) === 2 || (ar === 0 && ac === 0)) {
          matrix[ax + ar][ay + ac] = true;
        }
      }
    }

    // Hash text to generate pseudo-data modules
    var hash = 0;
    for (var h = 0; h < text.length; h++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(h);
      hash |= 0;
    }

    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        // Skip finder areas
        if ((r <= 8 && c <= 8) || (r <= 8 && c >= size - 8) || (r >= size - 8 && c <= 8)) continue;
        if (r === 6 || c === 6) continue;
        if (r >= 16 && r <= 20 && c >= 16 && c <= 20) continue;

        var bit = ((hash ^ (r * 31 + c * 17)) & 1) === 1;
        matrix[r][c] = bit;
      }
    }

    return matrix;
  }

  window.QRCode = QRCode;
})(window);
